// Sales report. Used by the finance export (export.js) and the weekly digest (digest.js).
// The layout is parsed by the finance team's import, so do not move columns around.
// TODO: US region once the tax rules are clear

const BULK_UNITS = 100;
const BULK_FACTOR = 0.95;
const LARGE_ORDER_AMOUNT = 10000;
const PRODUCT_WIDTH = 20;
const UNITS_WIDTH = 5;
const MONEY_WIDTH = 14;

// Regions appear in the report in this order. Sales of any other region are left out.
const REGIONS = [
  { code: 'DE', title: 'Germany', vatRate: 0.19 },
  { code: 'FR', title: 'France', vatRate: 0.2 },
  { code: 'UK', title: 'United Kingdom', vatRate: 0.2 },
];

function groupThousands(digits, separator) {
  const groups = [];
  for (let end = digits.length; end > 0; end -= 3) {
    groups.unshift(digits.slice(Math.max(0, end - 3), end));
  }
  return groups.join(separator);
}

export function formatMoney(amount, region) {
  const sign = amount < 0 ? '-' : '';
  const [integerPart, cents] = Math.abs(amount).toFixed(2).split('.');
  switch (region) {
    case 'DE':
      return sign + groupThousands(integerPart, '.') + ',' + cents + ' €';
    case 'FR':
      return sign + groupThousands(integerPart, ' ') + ',' + cents + ' €';
    case 'UK':
      return sign + '£' + groupThousands(integerPart, ',') + '.' + cents;
    default:
      throw new Error('unknown region: ' + region);
  }
}

function roundToCents(value) {
  return Math.round(value * 100) / 100;
}

// Net price after discount and bulk rebate, plus VAT, each step rounded to cents.
function grossAmount(sale, vatRate) {
  let net = sale.units * sale.unitPrice;
  if (sale.discountPct) {
    net -= (net * sale.discountPct) / 100;
  }
  if (sale.units >= BULK_UNITS) {
    net *= BULK_FACTOR;
  }
  net = roundToCents(net);
  return roundToCents(net + roundToCents(net * vatRate));
}

function truncate(text, width) {
  return text.length > width ? text.slice(0, width - 1) + '…' : text;
}

function formatRow(sale, amount, region) {
  const row =
    truncate(sale.product, PRODUCT_WIDTH).padEnd(PRODUCT_WIDTH) +
    ' ' +
    String(sale.units).padStart(UNITS_WIDTH) +
    ' ' +
    formatMoney(amount, region).padStart(MONEY_WIDTH);
  return amount >= LARGE_ORDER_AMOUNT ? row + ' *' : row;
}

function assertValidOptions({ format, month }) {
  if (format && format !== 'text') {
    throw new Error('unsupported format: ' + format);
  }
  if (month && !/^\d{4}-\d{2}$/.test(month)) {
    throw new Error('bad month: ' + month);
  }
}

function selectSales(sales, month) {
  const selected = month ? sales.filter((s) => s.date.slice(0, 7) === month) : sales.slice();
  return selected.sort((a, b) => (a.date < b.date ? -1 : a.date > b.date ? 1 : 0));
}

// Returns the report lines of one region (empty when it has no sales) and its row and large-order counts.
function buildRegionSection(sales, { code, title, vatRate }) {
  const regionSales = sales.filter((s) => s.region === code && s.units > 0);
  if (regionSales.length === 0) {
    return { lines: [], rows: 0, largeOrders: 0 };
  }
  const lines = ['== ' + title + ' =='];
  let subtotal = 0;
  let largeOrders = 0;
  for (const sale of regionSales) {
    const amount = grossAmount(sale, vatRate);
    lines.push(formatRow(sale, amount, code));
    subtotal += amount;
    if (amount >= LARGE_ORDER_AMOUNT) {
      largeOrders++;
    }
  }
  lines.push('Subtotal ' + code + ': ' + formatMoney(subtotal, code), '');
