  { region: 'DE', rep: 'Jonas', product: 'Gadget Mini', units: 3, unitPrice: 12.5, discountPct: 10, date: '2024-03-11' },
];

test('formats German amounts with dots and a euro sign', () => {
  assert.equal(formatMoney(1234.5, 'DE'), '1.234,50 €');
});

test('lists German sales with VAT and a subtotal', () => {
  const report = buildReport(germanSales);
  assert.equal(
    report,
    [
      'SALES REPORT',
      '',
      '== Germany ==',
      'Widget Pro              12       712,57 €',
      'Gadget Mini              3        40,16 €',
      'Subtotal DE: 752,73 €',
      '',
      'Rows: 2',
      'Large orders: 0',
      '',
    ].join('\n'),
  );
});

test('says so when there are no sales', () => {
  assert.equal(buildReport([]), 'SALES REPORT\n\nNo sales.\n');
});

const mixedSales = [
  { region: 'FR', rep: 'Claire', product: 'Widget Pro', units: 30, unitPrice: 51, date: '2024-03-12' },
  { region: 'UK', rep: 'Oliver', product: 'Gadget Mini', units: 80, unitPrice: 11.2, date: '2024-03-20' },
  { region: 'UK', rep: 'Priya', product: 'Premium Support Contract', units: 1, unitPrice: 9800, date: '2024-04-02' },
  { region: 'DE', rep: 'Jonas', product: 'Gadget Mini', units: 150, unitPrice: 12.5, discountPct: 10, date: '2024-03-11' },
  { region: 'US', rep: 'Sam', product: 'Widget Pro', units: 5, unitPrice: 10, date: '2024-03-01' },
  { region: 'DE', rep: 'Anke', product: 'Returned', units: 0, unitPrice: 10, date: '2024-03-02' },
];

test('groups sales by region, applies the bulk rebate, flags large orders and skips unknown regions and zero units', () => {
  assert.equal(
    buildReport(mixedSales),
    [
      'SALES REPORT',
      '',
      '== Germany ==',
      'Gadget Mini            150     1.907,72 €',
      'Subtotal DE: 1.907,72 €',
      '',
      '== France ==',
      'Widget Pro              30     1 836,00 €',
      'Subtotal FR: 1 836,00 €',
      '',
      '== United Kingdom ==',
      'Gadget Mini             80      £1,075.20',
      'Premium Support Con…     1     £11,760.00 *',
      'Subtotal UK: £12,835.20',
      '',
      'Rows: 4',
      'Large orders: 1',
      '',
    ].join('
'),
  );
});

test('restricts the report to one month and names it in the title', () => {
  assert.equal(
    buildReport(mixedSales, { month: '2024-04' }),
    [
      'SALES REPORT 2024-04',
      '',
      '== United Kingdom ==',
      'Premium Support Con…     1     £11,760.00 *',
      'Subtotal UK: £11,760.00',
      '',
      'Rows: 1',
      'Large orders: 1',
      '',
    ].join('
'),
  );
  assert.equal(buildReport(mixedSales, { month: '2025-01' }), 'SALES REPORT 2025-01

No sales.
');
});

test('rejects unsupported formats and malformed months', () => {
  assert.throws(() => buildReport(mixedSales, { format: 'legacy' }), /unsupported format: legacy/);
  assert.throws(() => buildReport(mixedSales, { format: 'csv' }), /unsupported format: csv/);
  assert.throws(() => buildReport(mixedSales, { month: 'March' }), /bad month: March/);
});

// Pins current behavior: the minus sign in row amounts is grouped like a digit (DE, UK) and
// follows the pound sign (UK), unlike the subtotal. Change only together with the finance import.
test('formats negative row amounts the way the finance import currently receives them', () => {
  const refunds = [
    { region: 'DE', product: 'Refund', units: 1, unitPrice: -100, date: '2024-03-01' },
    { region: 'FR', product: 'Refund', units: 1, unitPrice: -1000, date: '2024-03-01' },
    { region: 'UK', product: 'Refund', units: 1, unitPrice: -100000, date: '2024-03-01' },
  ];
  assert.equal(
    buildReport(refunds),
    [
      'SALES REPORT',
      '',
      '== Germany ==',
      'Refund                   1     -.119,00 €',
      'Subtotal DE: -119,00 €',
      '',
      '== France ==',
      'Refund                   1    -1 200,00 €',
      'Subtotal FR: -1 200,00 €',
      '',
      '== United Kingdom ==',
      'Refund                   1  £-,120,000.00',
      'Subtotal UK: -£120,000.00',
      '',
      'Rows: 3',
      'Large orders: 0',
      '',
    ].join('
'),
  );
});

test('formats French and British amounts, negatives and zero', () => {
  assert.equal(formatMoney(-1234567.891, 'FR'), '-1 234 567,89 €');
  assert.equal(formatMoney(-1234567.891, 'UK'), '-£1,234,567.89');
  assert.equal(formatMoney(0, 'DE'), '0,00 €');
  assert.throws(() => formatMoney(1, 'US'), /unknown region: US/);
});

